class Solution{public List<List<Integer>> fourSum(int[]A,int T){Arrays.sort(A);List<List<Integer>>R=new ArrayList<>();int Z=A.length;for(int I=0;I<Z-3;I++){if(I>0&&A[I]==A[I-1])continue;for(int l=I+1;l<Z-2;l++){if(l>I+1&&A[l]==A[l-1])continue;int Q=l+1,O=Z-1;while(Q<O){long S=(long)A[I]+A[l]+A[Q]+A[O];if(S==T){R.add(Arrays.asList(A[I],A[l],A[Q],A[O]));while(Q<O&&A[Q]==A[Q+1])Q++;while(Q<O&&A[O]==A[O-1])O--;Q++;O--;}else if(S<T)Q++;else O--;}}}return R;}}